package set_adapter

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "set_adapter"
	command.Identifiers = []string{"set-adapter"}
	command.Category = "Deps System"
	command.Help = "Changes which adapter an available binds for one dep"
	command.LongDescription = "Rewrites one available.yaml so the named adapter is the one bound for that dep, dropping whichever adapter filled the field before. It is the only editor of that choice."
	command.Examples = []string{"set-adapter sortdeps reflectsort", "set-adapter sortdeps reflectsort --available lambda"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "available",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the available to change (defaults to standard)",
			Examples:    []string{"set-adapter sortdeps reflectsort --available lambda"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--available"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"set-adapter sortdeps reflectsort --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{"set-adapter sortdeps reflectsort -q"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "dep",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the dep whose field is being filled",
			Examples:    []string{"set-adapter sortdeps reflectsort"},
			Default:     "",
			HasDefault:  false,
		},
		{
			Id:          "adapter",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the installed adapter that should fill it",
			Examples:    []string{"set-adapter sortdeps reflectsort"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
